SELECT id_imovel,area,SAFE_DIVIDE(ST_AREA(geometria),10000) area_geometria_ha,ST_Y(ST_CENTROID(geometria)) latitude,ST_X(ST_CENTROID(geometria)) longitude,status,condicao,tipo,data_criacao,data_atualizacao,data_extracao FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE id_imovel='BA-2929701-3438EBE3EC1C4160B13A7DC99112E048' AND data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY id_imovel ORDER BY data_extracao DESC)=1